function cmsOffers385(){ // 決定性三選一：同 seed 同輪次恆同；tech 型完成過不再出
  const elig=CMS385.filter(c=>rankIdx+1>=c.minRank&&!(c.type==='tech'&&cms385.done.includes(c.id)));
  if(elig.length<=3)return elig.slice();
  const out=[];let t=0;
  while(out.length<3&&t<60){const i=Math.floor(cmsHash385(seed|0,cms385.n*31+t,3850)*elig.length)%elig.length;if(out.indexOf(elig[i])<0)out.push(elig[i]);t++;}
  return out;
}

text.load:
function cmsLoad385(raw){ // 驗型失敗整欄棄用回零、任何路徑不拋（load 外層 try 會吞→蓋城）
  try{
    if(raw===undefined||raw===null)return emptyCms385();
    if(typeof raw!=='object'||Array.isArray(raw))return emptyCms385();
    const act=raw.act===undefined?'':raw.act;
    if(typeof act!=='string'||(act!==''&&!CMS_BY_ID385[act]))return emptyCms385();
    const o=emptyCms385();
    for(const k of ['st','acc','hold','n']){const v=raw[k]===undefined?0:raw[k];if(!Number.isInteger(v)||v<0)return emptyCms385();o[k]=v;}
    if(act!==''&&o.st<1)return emptyCms385();
    const rd=raw.done===undefined?[]:raw.done;
    if(!Array.isArray(rd))return emptyCms385();
    const seen={};
    for(const d2 of rd){if(typeof d2!=='string'||!CMS_BY_ID385[d2]||seen[d2])return emptyCms385();seen[d2]=1;o.done.push(d2);}
    if(act!==''&&seen[act])return emptyCms385(); // 語意非法：進行中不可已在完成清單
    o.act=act;return o;
  }catch(e){return emptyCms385();}
}

text.accept:
function cmsAccept385(i){
  if(diff===3||cms385.act||rankIdx+1<3||pop<=50)return false; // T386b 補課：T385 卡面宣稱的 pop>50 門檻
  const c=cmsOffers385()[i];if(!c)return false;
  cms385.act=c.id;cms385.st=day;cms385.acc=0;cms385.hold=0;
  toast('📋 接受委託：'+c.nm);return true;
}

text.drop:
function cmsDrop385(){
  if(!cms385.act)return false;
  const c=CMS_BY_ID385[cms385.act];
  cms385.act='';cms385.st=0;cms385.acc=0;cms385.hold=0;cms385.n++;
  toast('📋 放棄委託：'+(c?c.nm:''),'bad');return true;
}

text.daily:
/* ===== T385 cms BEGIN（委託逐日結算：純讀本 tick 已算值，零亂數；未接單=零模擬副作用＝
   兩釘種子在零接單路徑位元恆等；獎勵走一次性 money+=（里程碑先例，不入 income 防污染 fin/hist）） ===== */
if(diff!==3&&cms385.act){
  const cAct385=CMS_BY_ID385[cms385.act];
  if(cAct385){
    const el385=day-cms385.st;
    if(cAct385.type==='acc')cms385.acc+=cAct385.src==='steel'?steelUsed:cAct385.src==='trade'?tradeGold:0;
    else if(cAct385.type==='hold'){const v385=cAct385.src==='transit'?transitRidership:cAct385.src==='happy'?Math.round(cityHappy*100)/100:0;cms385.hold=v385>=cAct385.target?cms385.hold+1:0;} /* T394b：happy 判定改用 2dp 捨入值＝與面板顯示同源——原值 0.695 時面板顯 70% 卻不計數（T394a 實測 44 個唯一邊界日），玩家視角=被騙 */
    const stockV385=cAct385.type==='stock'?(cAct385.src==='steel'?steel:cAct385.src==='fuel'?fuel:0):0; // 純讀存量（零寫入紅線）
    const done385=cAct385.type==='acc'?cms385.acc>=cAct385.target:cAct385.type==='hold'?cms385.hold>=cAct385.holdN:cAct385.type==='tech'?hasTech343(cAct385.src):cAct385.type==='stock'?(el385>=cAct385.days&&stockV385>=cAct385.target):false; // stock=期末驗收
    if(done385){
      money+=cAct385.bonus;toast('📋 委託完成：'+cAct385.nm+'　+$'+cAct385.bonus,'gold');sFanfare();spawnConfetti();
      if(cms385.done.indexOf(cAct385.id)<0)cms385.done.push(cAct385.id);cms385.act='';cms385.st=0;cms385.acc=0;cms385.hold=0;cms385.n++; // done 只收不重複 id——重複完成照發獎但不重記，防重複項在下次 load 被驗型整欄棄用（測試抓到的真 bug）
    }else if(el385>=cAct385.days){
      toast('📋 委託過期：'+cAct385.nm,'bad'); // 失敗不毀城：零城市副作用（場景 lose 先例）
      cms385.act='';cms385.st=0;cms385.acc=0;cms385.hold=0;cms385.n++;
    }
  }else{cms385.act='';cms385.st=0;cms385.acc=0;cms385.hold=0;} // 白名單防禦（load 驗型已擋，此為雙保險）
}
/* ===== T385 cms END ===== */

